#include &lt;stdio.h&gt;

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--)
    {
        int n;
        long long int _min_val = 0;
        long long int _max_val = 0;
        scanf("%d", &n);
        int m = (n * (n - 1)) &gt;&gt; 1;
        int* edges = new int[m];

        for (int i = 0; i &lt; m; ++i)
        {
            scanf("%d", &edges[i]);
        }

        // 삽입 정렬 (오름차순)
        for (int j = 1; j &lt; m; ++j)
        {
            auto key = edges[j];
            int i = j - 1;
            while (i &gt;= 0 && edges[i] &gt; key)
            {
                edges[i + 1] = edges[i];
                --i;
            }
            edges[i + 1] = key;
        }

        for (int i = 0; i &lt; n - 1; ++i)
        {
            _min_val += edges[i];                  // Min MST: 가장 작은 N-1개
            _max_val += edges[(i * (i + 1)) / 2];  // Max MST: 삼각수 인덱스
        }

        printf("%lld %lld\n", _min_val, _max_val);
        delete[] edges;
    }
}

5.1 C++ 전체 코드
#include &lt;stdio.h&gt;

using ull = unsigned long long int;

ull _get_gcd(ull a, ull b)
{
    if(b == 0) return a;
    return _get_gcd(b, a % b);
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while(t--)
    {
        int A[50], B[50];
        int a, b;
        scanf("%d%d", &a, &b);
        for(int i = 0; i &lt; a; ++i) scanf("%d", &A[i]);
        for(int i = 0; i &lt; b; ++i) scanf("%d", &B[i]);

        // (1) 오름차순 정렬 (Insertion Sort)
        auto _insertion_sort = [](int n, int* arr) -&gt; void {
            for(int j = 1; j &lt; n; ++j)
            {
                auto key = arr[j];
                auto i = j - 1;
                while(i &gt;= 0 && arr[i] &gt; key)
                {
                    arr[i + 1] = arr[i];
                    --i;
                }
                arr[i + 1] = key;
            }
        };

        _insertion_sort(a, A);
        _insertion_sort(b, B);

        int _a, _b, _A[50], _B[50];
        _a = _b = 0;

        // (2) Redundant 원소 제거하여 canonical form 구성
        auto _get_frozen_set = [](int n, int* src, int* dst) -&gt; int {
            int cnt = 0;

            auto _get_lcm = [](ull a, ull b) -&gt; ull {
                return (a * b) / _get_gcd(a, b);
            };

            for(int i = 0; i &lt; n; ++i)
            {
                ull L = 1;
                for(int j = 0; j &lt; cnt; ++j)
                {
                    if((src[i] % dst[j]) != 0) continue;
                    L = _get_lcm(L, dst[j]);
                    if(L == src[i])
                    {
                        break;  // early termination: redundant 확정
                    }
                }
                if(L != src[i])
                {
                    dst[cnt++] = src[i];  // non-redundant 원소만 보존
                }
            }

            return cnt;
        };

        _a = _get_frozen_set(a, A, _A);
        _b = _get_frozen_set(b, B, _B);

        // (3) 두 canonical form 비교
        if(_a != _b)
        {
            printf("!\n");
        }
        else
        {
            int i = 0;
            for(; i &lt; _a; ++i)
            {
                if(_A[i] != _B[i]) break;
            }
            printf(i == _a ? "=\n" : "!\n");
        }
    }
}

5.2 핵심 부분 분석

5.2.1 Step 1: 오름차순 정렬
Insertion Sort를 사용. 입력 크기가 \(n \le 50\)으로 작아 \(O(n^2)\)로 충분.


5.2.2 Step 2: Canonical Form 구성
for(int i = 0; i &lt; n; ++i)
{
    ull L = 1;
    for(int j = 0; j &lt; cnt; ++j)
    {
        if((src[i] % dst[j]) != 0) continue;  // 약수가 아니면 skip
        L = _get_lcm(L, dst[j]);              // 누적 LCM 갱신
        if(L == src[i]) break;                // early termination
    }
    if(L != src[i]) dst[cnt++] = src[i];      // non-redundant
}
이 루프의 invariant:

시작 시점에서 dst[0..cnt-1]는 이미 처리된 \(a_1, \ldots, a_{i-1}\) 중 non-redundant 원소들의 정렬된 부분배열.
src[i]보다 작은 원소들 중 약수가 되는 것들의 누적 LCM을 L로 추적.
L == src[i] 시점에서 redundant 확정 (Lemma).
루프 종료 후 L != src[i]이면 non-redundant이므로 dst에 추가.



5.2.3 Step 3: 두 Canonical Form 비교
오름차순으로 정렬된 상태가 보존되므로, 길이 비교 후 원소별 선형 비교로 충분.

