}

7. 4단계 — 답 집계
ll total = 0;
for (int i = 0; i &lt; q; ++i) {
    total += (ll)(i + 1) * query[i].ans;
}
출력 합의 상한 \(\sim Q^2 \cdot K \approx 1.25 \times 10^{17}\), long long 안에 충분히 들어옴. 음수 누적 (\(\mathrm{ans} = -1\)) 가능하니 signed long long.

Codes
#include &lt;stdio.h&gt;

using ll = long long;

int t, n, m, k, q;
constexpr int MAX_N     = 500'001;
constexpr int MAX_M     = 1'500'001;
constexpr int MAX_K     = 500'001;
constexpr int MAX_Q     = 500'001;
constexpr int MAX_NODES = 2 * MAX_N;
constexpr int INF       = 1'000'000'000;
constexpr ll  SAFE_BND  = 1'500'000'000LL;

struct Building {
    int x, y;
    void init(int _x, int _y) { x = _x; y = _y; }
} building[MAX_N];

struct Bridge {
    int v1, v2;
    int broken_time;
    ll  lb;
} bridge[MAX_M];

struct Winter { int v, h; } winter[MAX_K];
struct Query  { int src, dst; ll ans; } query[MAX_Q];

int v_evt_cnt  [MAX_N];
int v_evt_start[MAX_N + 1];
int evt_day [MAX_K];
ll  evt_z   [MAX_K];
ll  evt_max [MAX_K];
ll  temp_z  [MAX_N];
ll  temp_max[MAX_N];

int par_uf [MAX_NODES];
int kru_l  [MAX_NODES];
int kru_r  [MAX_NODES];
ll  kru_val[MAX_NODES];
int tot_nodes;

int find_uf(int x) {
    while (par_uf[x] != x) {
        par_uf[x] = par_uf[par_uf[x]];
        x = par_uf[x];
    }
    return x;
}

int  tarjan_par    [MAX_NODES];
int  tarjan_anc    [MAX_NODES];
char tarjan_visited[MAX_NODES];

int qry_head [MAX_NODES];
int qry_next [2 * MAX_Q];
int qry_other[2 * MAX_Q];
int qry_idx  [2 * MAX_Q];
int qry_count;

void qry_add(int u, int v, int qid) {
    qry_other[qry_count] = v;
    qry_idx  [qry_count] = qid;
    qry_next [qry_count] = qry_head[u];
    qry_head [u]         = qry_count++;
}

int tarjan_find(int x) {
    while (tarjan_par[x] != x) {
        tarjan_par[x] = tarjan_par[tarjan_par[x]];
        x = tarjan_par[x];
    }
    return x;
}

int dfs_stack[MAX_NODES];
int dfs_phase[MAX_NODES];

void tarjan_lca_all(int root) {
    int sp = 0;
    dfs_stack[sp] = root;
    dfs_phase[sp] = 0;
    ++sp;
    while (sp &gt; 0) {
        int u = dfs_stack[sp - 1];
        int p = dfs_phase[sp - 1];
        if (p == 0) {
            tarjan_par[u] = u;
            tarjan_anc[u] = u;
            dfs_phase[sp - 1] = 1;
            if (kru_l[u]) {
                dfs_stack[sp] = kru_l[u];
                dfs_phase[sp] = 0;
                ++sp;
                continue;
            }
            p = 1;
        }
        if (p == 1) {
            if (kru_l[u]) {
                tarjan_par[tarjan_find(kru_l[u])] = u;
                tarjan_anc[tarjan_find(u)] = u;
            }
            dfs_phase[sp - 1] = 2;
            if (kru_r[u]) {
                dfs_stack[sp] = kru_r[u];
                dfs_phase[sp] = 0;
                ++sp;
                continue;
            }
            p = 2;
        }
        if (p == 2) {
            if (kru_r[u]) {
                tarjan_par[tarjan_find(kru_r[u])] = u;
                tarjan_anc[tarjan_find(u)] = u;
            }
            tarjan_visited[u] = 1;
            for (int qe = qry_head[u]; qe != -1; qe = qry_next[qe]) {
                int v = qry_other[qe];
                if (tarjan_visited[v]) {
                    int qid = qry_idx[qe];
                    int la = tarjan_anc[tarjan_find(v)];
                    ll val = kru_val[la];
                    query[qid].ans = (val &gt;= INF) ? -1LL : val;
                }
            }
            --sp;
        }
    }
}

void _qsort(int p, int r) {
    if (p &gt;= r) return;
    int pivot = bridge[(p + r) &gt;&gt; 1].broken_time;
    int lt = p, gt = r, i = p;
    while (i &lt;= gt) {
        if (bridge[i].broken_time &gt; pivot) {
            auto tmp = bridge[lt];
            bridge[lt] = bridge[i];
            bridge[i] = tmp;
            ++lt; ++i;
        } else if (bridge[i].broken_time &lt; pivot) {
            auto tmp = bridge[gt];
            bridge[gt] = bridge[i];
            bridge[i] = tmp;
            --gt;
        } else {
            ++i;
        }
    }
    _qsort(p, lt - 1);
    _qsort(gt + 1, r);
}

void reset_state() {
    tot_nodes = 0;
    qry_count = 0;
}

int main(void) {
    scanf("%d", &t);
    while (t--) {
        reset_state();

        scanf("%d", &n);
        for (int i = 1; i &lt;= n; ++i) {
            int x, y;
            scanf("%d%d", &x, &y);
            building[i].init(x, y);
        }

        scanf("%d", &m);
        for (int i = 0; i &lt; m; ++i) {
            ll l;
            scanf("%d%d%lld", &bridge[i].v1, &bridge[i].v2, &l);
            ll dx = building[bridge[i].v1].x - building[bridge[i].v2].x;
            ll dy = building[bridge[i].v1].y - building[bridge[i].v2].y;
            bridge[i].lb          = l * l - dx * dx - dy * dy;
            bridge[i].broken_time = INF;
        }

        scanf("%d", &k);
        for (int i = 0; i &lt; k; ++i) {
            scanf("%d%d", &winter[i].v, &winter[i].h);
        }

        scanf("%d", &q);
        for (int i = 0; i &lt; q; ++i) {
            scanf("%d%d", &query[i].src, &query[i].dst);
        }

        for (int v = 1; v &lt;= n; ++v) v_evt_cnt[v] = 0;
        for (int i = 0; i &lt; k; ++i) v_evt_cnt[winter[i].v]++;
        v_evt_start[1] = 0;
        for (int v = 1; v &lt;= n; ++v) v_evt_start[v + 1] = v_evt_start[v] + v_evt_cnt[v];

        for (int v = 1; v &lt;= n; ++v) {
            v_evt_cnt[v] = 0;
            temp_z[v]   = 0;
            temp_max[v] = 0;
        }
        for (int i = 0; i &lt; k; ++i) {
            int v = winter[i].v;
            temp_z[v] += winter[i].h;
            ll abs_z = temp_z[v] &lt; 0 ? -temp_z[v] : temp_z[v];
            if (abs_z &gt; temp_max[v]) temp_max[v] = abs_z;
            int idx = v_evt_start[v] + v_evt_cnt[v];
            evt_day[idx] = i;
            evt_z  [idx] = temp_z[v];
            evt_max[idx] = temp_max[v];
            v_evt_cnt[v]++;
        }

        for (int e = 0; e &lt; m; ++e) {
            int u = bridge[e].v1;
            int v = bridge[e].v2;
            ll lb_e = bridge[e].lb;
            int cu = v_evt_cnt[u];
            int cv = v_evt_cnt[v];
            int su = v_evt_start[u];
            int sv = v_evt_start[v];

            if (cu == 0 && cv == 0) continue;

            if (cv == 0) {
                int lo = su, hi = su + cu;
                while (lo &lt; hi) {
                    int mid = (lo + hi) &gt;&gt; 1;
                    ll mval = evt_max[mid];
                    bool broken = (mval &gt; SAFE_BND) || (mval * mval &gt; lb_e);
                    if (broken) hi = mid;
                    else        lo = mid + 1;
                }
                if (lo &lt; su + cu) bridge[e].broken_time = evt_day[lo] + 1;
            } else if (cu == 0) {
                int lo = sv, hi = sv + cv;
                while (lo &lt; hi) {
                    int mid = (lo + hi) &gt;&gt; 1;
                    ll mval = evt_max[mid];
                    bool broken = (mval &gt; SAFE_BND) || (mval * mval &gt; lb_e);
                    if (broken) hi = mid;
                    else        lo = mid + 1;
                }
                if (lo &lt; sv + cv) bridge[e].broken_time = evt_day[lo] + 1;
            } else {
                ll z_u = 0, z_v = 0;
                int pu = su, pv = sv;
                int eu = su + cu, ev = sv + cv;
                while (pu &lt; eu || pv &lt; ev) {
                    int day;
                    if (pu &lt; eu && (pv == ev || evt_day[pu] &lt;= evt_day[pv])) {
                        z_u = evt_z[pu];
                        day = evt_day[pu];
                        pu++;
                    } else {
                        z_v = evt_z[pv];
                        day = evt_day[pv];
                        pv++;
                    }
                    ll diff = z_u - z_v;
                    if (diff * diff &gt; lb_e) {
                        bridge[e].broken_time = day + 1;
                        break;
                    }
                }
            }
        }

        _qsort(0, m - 1);

        for (int i = 1; i &lt;= 2 * n; ++i) par_uf[i] = i;
        for (int i = 1; i &lt;= n;     ++i) kru_l[i] = kru_r[i] = 0;
        tot_nodes = n;

        for (int i = 0; i &lt; m; ++i) {
            int ru = find_uf(bridge[i].v1);
            int rv = find_uf(bridge[i].v2);
            if (ru == rv) continue;
            int w = ++tot_nodes;
            kru_val[w] = bridge[i].broken_time;
            kru_l[w] = ru;
            kru_r[w] = rv;
            par_uf[ru] = w;
            par_uf[rv] = w;
        }

        for (int i = 1; i &lt;= tot_nodes; ++i) {
            qry_head[i] = -1;
            tarjan_visited[i] = 0;
        }
        for (int i = 0; i &lt; q; ++i) {
            qry_add(query[i].src, query[i].dst, i);
            qry_add(query[i].dst, query[i].src, i);
        }
        tarjan_lca_all(tot_nodes);

        ll total = 0;
        for (int i = 0; i &lt; q; ++i) {
            total += (ll)(i + 1) * query[i].ans;
        }
        printf("%lld\n", total);
    }
    return 0;
}

8.1 Skip connections through time
ResNet/DenseNet의 시간축 버전. 멀리 떨어진 시점을 직접 연결.
h^{(t)} = f(h^{(t-1)}, x^{(t)}) + h^{(t-d)}

8.2 Leaky units
\mu^{(t)} \leftarrow \alpha\, \mu^{(t-1)} + (1-\alpha)\, v^{(t)}
지수이동평균(EMA) 형태. \alpha가 1에 가까우면 천천히 변하는 long-term 정보, 0에 가까우면 빠른 변화 추적. 무선통신의 EMA 기반 채널 추정과 동일한 구조다.

16.3 Masked Attention
때로 어떤 토큰이 어떤 토큰에 주의할지 제한하고 싶다. 어텐션 행렬을 마스킹해 구현한다:
\[
A_{ij} =
\begin{cases}
\mathrm{softmax}\ \text{값} & \text{허용}\\
0\ (\text{스코어}=-\infty) & \text{금지}
\end{cases}
\]
디코더에서 주로 쓰며, 미래 토큰이 아니라 과거 토큰에만 주의하도록 상삼각을 막는다(causal mask). 멀티모달 입력에서 선택적 데이터 인코딩에도 활용된다.

5.6 Indicator random variable 정의
다음 지시변수를 정의하자.
\[
X_{ij} = I\{A[j] \text{ falls in bucket } i\}
\]
즉,
\[
X_{ij} =
\begin{cases}
1 & \text{if } A[j] \text{가 bucket } i \text{에 들어가면}, \\
0 & \text{otherwise.}
\end{cases}
\]
그러면 bucket \(i\)의 원소 수는 \[
n_i = \sum_{j=0}^{n-1} X_{ij}
\] 이다.

MDP는 완전 관측 가능(fully observable) 환경을 형식화하는 표준 틀이다. “현재 상태가 미래를 결정하는 데 필요한 모든 정보를 담고 있다”는 Markov 성질 위에, 보상(reward) 과 행동(action) 을 차례로 얹어 나가는 구조를 갖는다.

\underbrace{\langle S, P\rangle}_{\text{Markov Process}}
\;\xrightarrow{+\,R,\;\gamma}\;
\underbrace{\langle S, P, R, \gamma\rangle}_{\text{MRP}}
\;\xrightarrow{+\,A}\;
\underbrace{\langle S, A, P, R, \gamma\rangle}_{\text{MDP}}







중요한 문장으로 압축한 핵심



MDP에 정책 \pi를 고정하면 즉시 MRP가 되고, MRP는 다시 Markov Process가 된다. 따라서 정책 평가(evaluation)는 언제나 “유도된 MRP의 가치 계산”으로 환원된다.

5.3 최적 정책 찾기
q_*를 알면 즉시 greedy하게 결정적(deterministic) 정책을 얻는다.

\pi_*(a\mid s) =
\begin{cases}
1 & \text{if } a = \arg\max_{a\in A} q_*(s,a)\\
0 & \text{otherwise}
\end{cases}







중요



결정적 최적 정책은 항상 존재한다. 즉 q_*만 구하면 MDP는 끝난다.

12.2 행렬 관점
일반 Conv를 행렬 곱으로 표현:

\mathbf{y} = \mathbf{C}\mathbf{x}

여기서 \mathbf{C}는 Toeplitz 구조의 convolution matrix.
Transposed Convolution:

\mathbf{y} = \mathbf{C}^\top \mathbf{x}

전치행렬을 곱하는 것이지, 역행렬을 곱하는 것이 아니다.

\mathbf{C}^\top \neq \mathbf{C}^{-1}

4.1 CLIP (OpenAI, 2021)
CLIP(Contrastive Language–Image Pre-training)은 가장 널리 쓰이는 멀티모달 공동 임베딩 기법이다.

이미지 인코더(ViT/CNN)와 텍스트 인코더(Transformer)가 각각 임베딩을 만든다.
대조 학습(contrastive learning) 으로 “맞는 (이미지, 텍스트) 쌍”의 임베딩은 가깝게, “틀린 쌍”은 멀게 만든다.
결과적으로 zero-shot 분류(태스크별 fine-tuning 없이 분류)가 가능해진다.


4.1.1 대조 사전학습(Contrastive pre-training)의 메커니즘
미니배치 N개의 (이미지, 텍스트) 쌍에서 모든 쌍의 내적(유사도) 행렬을 만든다. 대각선(I_i\cdot T_i)이 정답(positive), 나머지가 오답(negative)이다.
이미지 임베딩 I_i, 텍스트 임베딩 T_j (L2 정규화됨), 온도 \tau에 대해 로짓 \ell_{ij} = I_i^\top T_j / \tau. 손실은 행 방향(이미지→텍스트)과 열 방향(텍스트→이미지) 교차 엔트로피의 평균이다.

\mathcal{L}_{\text{CLIP}}
= \frac{1}{2N}\sum_{i=1}^{N}
\Bigg[
\underbrace{-\log\frac{e^{\ell_{ii}}}{\sum_{j} e^{\ell_{ij}}}}_{\text{이미지}\to\text{텍스트}}
\;+\;
\underbrace{-\log\frac{e^{\ell_{ii}}}{\sum_{j} e^{\ell_{ji}}}}_{\text{텍스트}\to\text{이미지}}
\Bigg]

핵심: softmax가 미니배치 전체에 대해 걸린다. 즉 한 이미지에 대해 “배치 안 모든 텍스트 중 정답 고르기”라는 N지선다 분류 문제다.

유한한 데이터 \(\mathcal{D}=\{(\bm{x}_i,y_i)\}_{i=1}^N\) 로 학습한 추정량 \(\hat{f}_\mathcal{D}\) 의 기대 제곱 오차는 다음처럼 분해된다.
\[
\underbrace{\mathbb{E}_{\mathcal{D}}\!\left[(\hat{f}_\mathcal{D}(\bm{x}) - f^*(\bm{x}))^2\right]}_{\text{기대 오차}}
= \underbrace{\left(\mathbb{E}_\mathcal{D}[\hat{f}_\mathcal{D}(\bm{x})] - f^*(\bm{x})\right)^2}_{\text{Bias}^2}
+ \underbrace{\mathbb{E}_\mathcal{D}\!\left[(\hat{f}_\mathcal{D}(\bm{x}) - \mathbb{E}_\mathcal{D}[\hat{f}_\mathcal{D}(\bm{x})])^2\right]}_{\text{Variance}}
\tag{1}\]
심층 신경망은 표현력(capacity)이 커서 분산이 지배적인 영역에서 동작하기 쉽다. 정규화는 약간의 편향을 받아들이는 대신 분산을 크게 깎아 식 1 의 총합을 낮춘다.






Note통계적 추론 관점



정규화는 ill-posed 역문제(inverse problem)를 well-posed로 바꾸는 작업과 동형이다. 무선통신에서 안테나 수보다 추정해야 할 경로(path)가 많을 때(under-determined), 채널이 희소(sparse)하다는 사전지식을 \(\ell_1\) 페널티로 넣어 해를 유일하게 만드는 것 — 이것이 바로 compressed sensing이며, 정규화의 전형적 사례다.

2.3 토큰의 선형 조합과 .z 표기
뉴런의 선형 조합은 스칼라 가중합이다:
x_\text{out} = \sum_{i=1}^N w_i \, x_{\text{in}_i}
토큰의 선형 조합도 본질은 같지만, 단위가 벡터이므로 표기가 달라진다:
t_\text{out}.\mathbf{z} = \sum_{i=1}^N w_i \, t_{\text{in}_i}.\mathbf{z}






Important.z 표기의 의미



.z는 토큰 벡터의 특정 차원(element)을 가리키는 인덱싱 표기다. 즉 위 수식은 “출력 토큰의 z번째 차원은, 입력 토큰들의 z번째 차원의 가중합이다” 라는 뜻이며, 이는 모든 차원에 대해 동일한 가중치 w_i가 적용된다는 사실을 명시적으로 드러낸다.
벡터 표기로 다시 쓰면 단순하다: \mathbf{t}_\text{out} = \sum_{i=1}^N w_i \, \mathbf{t}_{\text{in}_i}


이 element-wise 동일 가중치 구조가 바로 attention의 Value 가중합과 정확히 일치한다.

6 코드
#include &lt;stdio.h&gt;
#include &lt;unordered_map&gt;

using ull = unsigned long long int;
int n;
ull x, a[60], ub[60];
std::unordered_map&lt;ull, ull&gt; dp[60];

ull solve(int idx, ull mask)
{
    if (idx &lt; 0) return 1;
    if (dp[idx].find(mask) != dp[idx].end()) return dp[idx][mask];
    ull& ans = dp[idx][mask] = 0;

    ull constraints = mask;
    if (idx &lt; n) {
        if (ub[idx] &lt; (1ULL &lt;&lt; (idx + 1))) {
            constraints |= (1ULL &lt;&lt; idx);
        }
    }

    for (int val = 0; val &lt;= 1; ++val) {
        bool is_valid = true;
        ull new_mask = 0x00;

        for (int c = 0; c &lt; n; ++c) {
            if ((constraints &gt;&gt; c) & 1) {
                int req_bit = ((ub[c] &gt;&gt; idx) & 1);
                if (val &gt; req_bit) {
                    is_valid = false;
                    break;
                }
                if (val == req_bit) {
                    new_mask |= (1LL &lt;&lt; c);
                }
            }
        }
        if (is_valid) {
            ans += solve(idx - 1, new_mask);
        }
    }

    return ans;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--) {
        ull s = 0;
        scanf("%d %llu", &n, &x);
        for (int i = 0; i &lt; 60; ++i) dp[i].clear();
        for (int i = 0; i &lt; n; ++i) {
            scanf("%llu", &a[i]);
            s += a[i] &lt;&lt; i;
            ub[i] = s / x;
        }

        printf("%llu\n", solve(59, (1ULL &lt;&lt; n - 1)));
    }
}

6. Codes
#include &lt;stdio.h&gt;

#define MAX_V   (100'000)
#define MAX_E   (100'000)

unsigned long long int ans;
int n, m, k;
int color[MAX_V];

int edge_u[MAX_E];
int edge_v[MAX_E];

int deg_[MAX_V];
int head_[MAX_V + 1];
int pos_[MAX_V + 1];

int adj_list[MAX_E &lt;&lt; 1];

void build_csr()
{
    for(int i = 0; i &lt; n; ++i)
        deg_[i] = 0;

    for(int i = 0; i &lt; m; ++i) {
        ++deg_[edge_u[i]];
        ++deg_[edge_v[i]];
    }

    head_[0] = pos_[0] = 0;
    for(int v = 1; v &lt;= n; ++v) {
        head_[v] = head_[v - 1] + deg_[v - 1];
        pos_[v] = head_[v];
    }

    for(int i = 0; i &lt; m; ++i) {
        adj_list[pos_[edge_u[i]]++] = edge_v[i];
        adj_list[pos_[edge_v[i]]++] = edge_u[i];
    }
}

unsigned long long int dp[MAX_V][0b100000][2];

int main(void)
{
    int t;
    scanf("%d", &t);
    while(t--) {
        scanf("%d%d%d", &n, &m, &k);
        for(int i = 0; i &lt; n; ++i) {
            scanf("%d", &color[i]);
            --color[i];
        }
        for(int i = 0; i &lt; m; ++i) {
            int u, v;
            scanf("%d%d", &u, &v);
            --u, --v;
            edge_u[i] = u;
            edge_v[i] = v;
        }
        build_csr();

        const int full_mask = (1 &lt;&lt; k) - 1;
        ans = 0;
        int cursor = 0;

        for(int v = 0; v &lt; n; ++v) {
            for(int mask = 0; mask &lt;= full_mask; ++mask)
                dp[v][mask][cursor] = 0;
            dp[v][1 &lt;&lt; color[v]][cursor] = 1;
        }

        for(int len = 1; len &lt; k; ++len) {
            for(int v = 0; v &lt; n; ++v)
                for(int mask = 0; mask &lt;= full_mask; ++mask)
                    dp[v][mask][cursor ^ 0x01] = 0;

            for(int v = 0; v &lt; n; ++v) {
                for(int mask = 0; mask &lt;= full_mask; ++mask) {
                    auto& curr = dp[v][mask][cursor];
                    if(curr == 0) continue;

                    for(int i = head_[v]; i &lt; head_[v + 1]; ++i) {
                        int u = adj_list[i];
                        int c_bit = color[u];
                        if(mask & (1 &lt;&lt; c_bit)) continue;

                        dp[u][mask | (1 &lt;&lt; c_bit)][cursor ^ 0x01] += curr;
                    }
                }
            }

            for(int v = 0; v &lt; n; ++v)
                for(int mask = 0; mask &lt;= full_mask; ++mask)
                    ans += dp[v][mask][cursor ^ 0x01];

            cursor ^= 0x01;
        }
        printf("%llu\n", ans);
    }
}

5. open addressing 구현 시 주의할 점
벡터 \((x,y)\)를 키로 쓰는 해시테이블을 직접 구현할 때 두 가지 함정이 있었다.

5.1 종료 조건에 탐사 대상 값 자체를 쓰지 말 것
do {
    if (h_table[key].can_be_alloc(cp_a, cp_b)) return key;
} while (key = (key + 1) % MAX_TABLE);
이 패턴은 key가 선형 탐사 중 0으로 wraparound되는 순간 while 조건이 거짓이 되어 탐사가 충돌이 남아 있는데도 조기 종료된다. 실제로 무작위 \((at, cg)\) 쌍을 채워 load factor를 높이면, 탐사 거리가 길어질수록 거의 항상 이 조기 종료가 발생한다.






Warning



샘플 입력 \(N \le 5000\) 정도로는 테이블이 충분히 비어 있어 우연히 이 버그를 피해갈 수 있다. 종료 조건을 “다음 인덱스의 값”에 의존시키지 말고, 탐사 횟수를 별도 카운터로 제한해야 한다.


올바른 형태:
for (int tries = 0; tries &lt; MAX_TABLE; ++tries) {
    if (h_table[key].can_be_alloc(cp_a, cp_b)) return key;
    key = (key + 1) % MAX_TABLE;
}


5.2 초기화 오타는 우연히 무해할 수 있다
h_table[get_key(0, 0)].key_AT = h_table[0].key_CG = 0;
get_key(0, 0)이 실제로 가리키는 슬롯과 인덱스 0번 슬롯이 다를 수 있다. 이 경우 슬롯 0이 key_AT = -1, key_CG = 0인 반쪽 상태로 오염되지만, 바로 다음 줄에서 get_key(0,0)을 다시 호출해 정상 슬롯의 count를 세팅하므로 최종 정답에는 영향이 없다. 다만 이후 다른 입력에서 우연히 슬롯 0이 필요해지면 can_be_alloc의 비교 로직이 잘못된 결과를 낼 수 있는 잠재적 위험이 남는다.

7. Codes
#include &lt;stdio.h&gt;

unsigned long long int ans;
#define MAX_TABLE   (10007)
struct HashTable {
    int key_AT;
    int key_CG;
    int count;

    void init() {
        key_AT = key_CG = -1;
        count = 0;
    }

    bool can_be_alloc(int at, int cg) {
        if(key_AT == -1) {
            key_AT = at;
            key_CG = cg;

            return true;
        }
        return (key_AT == at && key_CG == cg);
    }
} h_table[MAX_TABLE];

int len;
char str[5001];

unsigned long get_key(long long at, long long cg)
{
    auto cp_a = at;
    auto cp_b = cg;
    at += 5000;
    cg += 5000;

    int key = ((at &lt;&lt; 14) + cg) % MAX_TABLE;
    do {
        if(h_table[key].can_be_alloc(cp_a, cp_b)) return key;
        key = (key + 1) % MAX_TABLE;
    } while(true);

    return 987654321ULL;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while(t--) {
        scanf("%d %s", &len, str);

        for(int i = 0; i &lt; MAX_TABLE; ++i) {
            h_table[i].init();
        }
        h_table[get_key(0, 0)].key_AT = h_table[0].key_CG = 0;
        h_table[get_key(0, 0)].count = 1;

        ans = 0;
        int at = 0;
        int cg = 0;
        for(int i = 0; i &lt; len; ++i) {
            switch(str[i]) {
                case 'A': ++at; break;
                case 'T': --at; break;
                case 'C': ++cg; break;
                case 'G': --cg; break;
                default: break;
            }

            auto key = get_key(at, cg);
            ans += h_table[key].count;
            ++h_table[key].count;
        }

        printf("%llu\n", ans);
    }
}

