#define MAX_RIDES   (100)
#define MAX_SIZE    (10'000)

int cur_time;

struct HeapArgument {
    int count;
    int priority;

    HeapArgument()
    {}

    HeapArgument(int _c, int _p) {
        count = _c;
        priority = _p;
    }

    bool operator &gt; (const HeapArgument& Other) {
        return (priority &gt; Other.priority);
    }
};

struct Heap {
    HeapArgument heap[MAX_SIZE];
    int size;
    int tot_cnt;

    void init() {
        size = 0;
        tot_cnt = 0;
    }

    void push(HeapArgument arg) {
        heap[size] = arg;
        tot_cnt += arg.count;

        int current = size;
        while (current &gt; 0 && heap[current] &gt; heap[(current - 1) / 2]) 
        {
            auto temp = heap[(current - 1) / 2];
            heap[(current - 1) / 2] = heap[current];
            heap[current] = temp;
            current = (current - 1) / 2;
        }

        ++size;
    }

    HeapArgument pop()
    {
        auto ret = heap[0];
        tot_cnt -= ret.count;
        --size;

        heap[0] = heap[size];

        int current = 0;
        while (current * 2 + 1 &lt; size)
        {
            int child;
            if (current * 2 + 2 == size)
            {
                child = current * 2 + 1;
            }
            else
            {
                child = heap[current * 2 + 1] &gt; heap[current * 2 + 2] ? current * 2 + 1 : current * 2 + 2;
            }

            if (heap[current] &gt; heap[child])
            {
                break;
            }

            auto temp = heap[current];
            heap[current] = heap[child];
            heap[child] = temp;

            current = child;
        }
        return ret;
    }
};

int n_rides;
struct Rides {
    int id;
    int duration;
    int cap;
    int end_time;

    bool is_on_operation() {
        return (end_time &gt; cur_time);
    }

    int get_highest_pri() {
        if(pque.size == 0) return 0;
        return pque.heap[0].priority;
    }

    void flush_queue() {
        if (end_time == -1) {
            return;
        }
        if (is_on_operation()) {
            return;
        }
        if (pque.size == 0) {
            return;
        }

        int factor = (cur_time - end_time + duration - 1) / duration;
        int need = (pque.tot_cnt + cap - 1) / cap;
        int runs = factor &lt; need ? factor : need;
        int tot_cap = runs * cap;

        int cnt = 0;
        while (tot_cap &gt; cnt) {
            if (pque.size == 0) {
                break;
            }
            int t_cnt = pque.heap[0].count;
            if (t_cnt + cnt &lt;= tot_cap) {
                cnt += t_cnt;
                pque.pop();
            }
            else {
                pque.heap[0].count -= (tot_cap - cnt);
                pque.tot_cnt -= (tot_cap - cnt);
                break;
            }
        }

        end_time += duration * runs;
    }

    void board_now() {
        if (is_on_operation()) {
            return;
        }
        if (pque.size == 0) {
            return;
        }

        int cnt = 0;
        while (cap &gt; cnt) {
            if (pque.size == 0) {
                break;
            }
            int t_cnt = pque.heap[0].count;
            if (t_cnt + cnt &lt;= cap) {
                cnt += t_cnt;
                pque.pop();
            }
            else {
                pque.heap[0].count -= (cap - cnt);
                pque.tot_cnt -= (cap - cnt);
                break;
            }
        }

        end_time = cur_time + duration;
    }

    Heap pque;
} rides[MAX_RIDES];

void init(int N, int mId[], int mDuration[], int mCapacity[]) {
    cur_time = 0;

    n_rides = N;
    for(int i = 0; i &lt; n_rides; ++i) {
        rides[i].id = mId[i];
        rides[i].duration = mDuration[i];
        rides[i].cap = mCapacity[i];
        rides[i].pque.init();
        rides[i].end_time = -1;
    }

    return;
}

int get_ride_id(int m_id) {
    for(int i = 0; i &lt; n_rides; ++i) {
        if(rides[i].id == m_id) return i;
    }

    return -1;
}

int add(int tStamp, int mId, int mNum, int mPriority) {
    cur_time = tStamp;

    HeapArgument arg(mNum, mPriority);

    int r_id = get_ride_id(mId);
    auto& target = rides[r_id];

    target.flush_queue();
    target.pque.push(arg);

    if(target.end_time == -1) {
        target.end_time = cur_time;
    }

    target.board_now();

    return target.get_highest_pri();
}

void search(int tStamp, int mCount, int mId[], int mWait[]) {
    cur_time = tStamp;

    for(int i = 0; i &lt; n_rides; ++i) {
        rides[i].flush_queue();
        rides[i].board_now();
    }

    for(int i = 0; i &lt; 10; ++i) {
        mId[i] = mWait[i] = -1;
    }

    for(int i = 0; i &lt; n_rides; ++i) {
        int j = mCount - 1;
        for(;j &gt;= 0;) {
            bool cond1 = (rides[i].pque.tot_cnt &gt; mWait[j]);
            bool cond2 = (rides[i].pque.tot_cnt == mWait[j]) && (rides[i].id &gt; mId[j]);
            if(cond1 || cond2) {
                --j;
            }
            else break;
        }
        for(int k = mCount - 2; k &gt;= j + 1; --k) {
            mId[k + 1] = mId[k];
            mWait[k + 1] = mWait[k];
        }
        if(j + 1 &lt;= mCount - 1) {
            mId[j + 1] = rides[i].id;
            mWait[j + 1] = rides[i].pque.tot_cnt;
        }
    }

    return;
}

Codes
#include &lt;stdio.h&gt;

using ull = unsigned long long int;

#define MAX_N   (20'001)
#define MAX_GRP (6)
#define HCAP (1 &lt;&lt; 17)
#define H_EMPTY    0
#define H_OCCUPIED 1
#define H_DELETED  2

struct Hash {
    int state[HCAP];
    int id_[HCAP];
    int grade_[HCAP], gender_[HCAP], score_[HCAP];

    void init() {
        for (int i = 0; i &lt; HCAP; i++) state[i] = H_EMPTY;
    }

    int hslot(int id) {
        return (int)(((unsigned)id * 2654435761u) & (HCAP - 1));
    }

    int find(int id) {
        int i = hslot(id);
        while (state[i] != H_EMPTY) {
            if (id_[i] == id && state[i] == H_OCCUPIED) return i;
            i = (i + 1) & (HCAP - 1);
        }
        return -1;
    }

    void insert(int id, int g, int gen, int sc) {
        int i = hslot(id);
        while (state[i] == H_OCCUPIED) {
            i = (i + 1) & (HCAP - 1);
        }

        state[i] = H_OCCUPIED;
        id_[i] = id; grade_[i] = g; gender_[i] = gen; score_[i] = sc;
    }

    void erase_slot(int i) {
        state[i] = H_DELETED;
    }
} ht;

struct Treap {
    int pool_top;
    int free_top;
    int free_list[MAX_N];

    ull key_[MAX_N];
    ull pri_[MAX_N];
    int lc_[MAX_N], rc_[MAX_N];
    int root;

    ull seed;
    unsigned int pseudo_rand() {
        seed = seed * 25214903917ULL + 11ULL;
        return (seed &gt;&gt; 16) & 0x3fffffff;
    }

    void init() {
        pool_top = free_top = 0;
        root = 0;
        seed = 6545344357ULL;
    }

    int alloc_node(ull k) {
        int x;
        if(free_top &gt; 0) x = free_list[--free_top];
        else x = ++pool_top;
        key_[x] = k;
        pri_[x] = pseudo_rand();
        lc_[x] = rc_[x] = 0;

        return x;
    }

    int rotate_left(int p) {
        int c = rc_[p];
        rc_[p] = lc_[c];
        lc_[c] = p;
        return c;
    }

    int rotate_right(int p) {
        int c = lc_[p];
        lc_[p] = rc_[c];
        rc_[c] = p;
        return c;
    }

    void insert(ull k) {
        int x = alloc_node(k);
        if (root == 0) {
            root = x;
            return;
        }

        int path[64], pdir[64], top = 0;
        int cur = root;
        while (cur) {
            path[top] = cur;
            if(k &lt; key_[cur]) {
                pdir[top] = 0;
                cur = lc_[cur];
            }
            else {
                pdir[top] = 1;
                cur = rc_[cur];
            }
            ++top;
        }

        int par = path[top - 1];
        if(pdir[top - 1] == 0) {
            lc_[par] = x;
        }
        else {
            rc_[par] = x;
        }

        while(top &gt; 0 && pri_[x] &gt; pri_[path[top - 1]]) {
            int p = path[top - 1];
            int sub;
            if(pdir[top - 1] == 0) sub = rotate_right(p);
            else sub = rotate_left(p);

            --top;

            if(top == 0) {
                root = sub;
            }
            else if (pdir[top - 1] == 0) {
                lc_[path[top - 1]] = sub;
            }
            else {
                rc_[path[top - 1]] = sub;
            }
        }
    }

    int erase(ull k) {
        int cur = root;
        int par = 0;
        int dir = 0;

        while(cur && key_[cur] != k) {
            par = cur;
            if(k &lt; key_[cur]) {
                dir = 0;
                cur = lc_[cur];
            }
            else {
                dir = 1;
                cur = rc_[cur];
            }
        }

        if(cur == 0) return 0;

        int t = cur;
        while(lc_[t] && rc_[t]) {
            int sub;
            int t_dir;
            if(pri_[lc_[t]] &gt; pri_[rc_[t]]) {
                sub = rotate_right(t);
                t_dir = 1;
            }
            else {
                sub = rotate_left(t);
                t_dir = 0;
            }

            if(par == 0) {
                root = sub;
            }
            else if (dir == 0) {
                lc_[par] = sub;
            }
            else {
                rc_[par] = sub;
            }

            par = sub;
            dir = t_dir;
        }

        int child = lc_[t] ? lc_[t] : rc_[t];
        if(par == 0) {
            root = child;
        }
        else if(dir == 0) {
            lc_[par] = child;
        }
        else {
            rc_[par] = child;
        }

        free_list[free_top++] = t;
        return 1;
    }

    ull find_min() {
        if(root == 0) return 0;
        int cur = root;
        while(lc_[cur]) cur = lc_[cur];
        return key_[cur];
    }

    ull find_max() {
        if(root == 0) return 0;
        int cur = root;
        while(rc_[cur]) cur = rc_[cur];
        return key_[cur];
    }

    ull lower_bound(ull k) {
        int cur = root;
        ull best = 0;
        while(cur) {
            if(key_[cur] &gt;= k) {
                best = key_[cur];
                cur = lc_[cur];
            }
            else {
                cur = rc_[cur];
            }
        }

        return best;
    }
} treap[MAX_GRP];

constexpr ull id_filter = ((1 &lt;&lt; 30) - 1);

void init() {
    for(int i = 0; i &lt; MAX_GRP; ++i) treap[i].init();
    ht.init();
}

int add(int mId, int mGrade, char mGender[7], int mScore) {
    int gen = (mGender[0] == 'm' ? 0 : 1);
    int g = ((mGrade - 1) &lt;&lt; 1) + gen;
    ull k =  ((ull)mScore &lt;&lt; 30) | (ull) mId;

    treap[g].insert(k);
    ht.insert(mId, mGrade, gen, mScore);

    return treap[g].find_max() & id_filter;
}

int remove(int mId) {
    auto slot = ht.find(mId);
    if(slot == -1) return 0;

    int g = ((ht.grade_[slot] - 1) &lt;&lt; 1) + ht.gender_[slot];
    ull k = ((ull)ht.score_[slot] &lt;&lt; 30) | (ull) ht.id_[slot];

    treap[g].erase(k);
    ht.erase_slot(slot);

    auto m = treap[g].find_min();
    if(m == 0) return 0;
    return m & id_filter;
}

int query(int mGradeCnt, int mGrade[], int mGenderCnt, char mGender[][7], int mScore) {
    ull best = 0;

    for(int grd = 0; grd &lt; mGradeCnt; ++grd) {
        for(int gen = 0; gen &lt; mGenderCnt; ++gen) {
            int grp = ((mGrade[grd] - 1) &lt;&lt; 1) + (mGender[gen][0] == 'm' ? 0 : 1);
            auto lb = treap[grp].lower_bound((ull)mScore &lt;&lt; 30);
            if(lb != 0) {
                if(best == 0 || lb &lt; best) {
                    best = lb;
                }
            }
        }
    }

    if(best == 0) return 0;

    return best & id_filter;
}

6. 최상위 비트: 대칭이 깨지는 지점
lowbit과 달리 최상위 비트를 뽑는 두-연산짜리 산술 트릭은 존재하지 않는다. lowbit의 엔진은 캐리 전파인데, 덧셈의 캐리는 항상 낮은 자리에서 높은 자리로만 흐른다. 최상위 비트를 뽑으려면 정보가 높은 자리에서 낮은 자리로 흘러야 하고, 기본 연산 중 이를 수행하는 것은 오른쪽 시프트뿐이다.
방법 1 — 비트 스미어링(smearing): 시프트-OR로 최상위 1비트를 아래로 번지게 한 뒤, 연속 1 마스크에서 최상위만 남긴다.
unsigned int highbit(unsigned int x)
{
    x |= x &gt;&gt; 1;
    x |= x &gt;&gt; 2;
    x |= x &gt;&gt; 4;
    x |= x &gt;&gt; 8;
    x |= x &gt;&gt; 16;
    return x - (x &gt;&gt; 1);
}
각 단계가 “번진 폭”을 두 배로 늘리므로 32비트는 5단계면 충분하다.






Warning



마지막 줄을 \((x+1) \gg 1\)로 쓰면 \(x = \texttt{0xFFFFFFFF}\)일 때 \(x+1\)이 오버플로한다. 뺄셈 형태 \(x - (x \gg 1)\)이 안전하다.


방법 2 — 하드웨어 명령: __builtin_clz(x)는 leading zero 개수를 세는 컴파일러 내장 함수(인트린식)라 별도 헤더가 필요 없다. 단 \(x = 0\)이면 정의되지 않은 동작이며, 채점 환경의 컴파일러가 불명확하면 단순 루프가 가장 안전하다.
highbit이 실전에서 쓰이는 대표적인 곳은 BIT 위에서의 k번째 원소 탐색이다. 트리 최상단(\(n\) 이하의 가장 큰 2의 거듭제곱)에서 시작해 절반씩 내려오는 이진 탐색으로, 접두사 합이 처음으로 \(k\) 이상이 되는 인덱스를 \(O(\log n)\)에 찾는다.

Codes
#define MAX_N       (100'000)
#define MAX_TYPE    (1'000)

static int n_;
static int time_[MAX_N];
static long long bit_[MAX_N + 1];
static int head_[MAX_TYPE];
static int next_[MAX_N];

static void bit_add(int i, long long d)
{
    for (; i &lt;= n_; i += i & (-i)) bit_[i] += d;
}

static long long bit_sum(int i)
{
    long long s = 0;
    for (; i &gt; 0; i -= i & (-i)) s += bit_[i];
    return s;
}

void init(int N, int M, int mType[], int mTime[])
{
    n_ = N - 1;

    for (int i = 0; i &lt;= n_; ++i) bit_[i] = 0;
    for (int i = 0; i &lt; M; ++i) head_[i] = -1;

    for (int i = 0; i &lt; n_; ++i) {
        time_[i] = mTime[i];
        bit_add(i + 1, mTime[i]);
        next_[i] = head_[mType[i]];
        head_[mType[i]] = i;
    }
}

void destroy()
{
}

void update(int mID, int mNewTime)
{
    bit_add(mID + 1, (long long)mNewTime - time_[mID]);
    time_[mID] = mNewTime;
}

int updateByType(int mTypeID, int mRatio256)
{
    long long total = 0;
    for (int i = head_[mTypeID]; i != -1; i = next_[i]) {
        long long nt = ((long long)time_[i] * mRatio256) &gt;&gt; 8;
        bit_add(i + 1, nt - time_[i]);
        time_[i] = (int)nt;
        total += nt;
    }
    return (int)total;
}

int calculate(int mA, int mB)
{
    if (mA &gt; mB) { int t = mA; mA = mB; mB = t; }
    return (int)(bit_sum(mB) - bit_sum(mA));
}

2.1 편향-분산 분해
새로운 입력 \(x_0\)에서의 기대 예측 오차는 다음과 같이 분해된다.
\[
\mathbb{E}\left[(y_0 - \hat f(x_0))^2\right]
= \underbrace{\left(\mathbb{E}[\hat f(x_0)] - f(x_0)\right)^2}_{\text{편향}^2}
+ \underbrace{\mathbb{E}\left[(\hat f(x_0) - \mathbb{E}[\hat f(x_0)])^2\right]}_{\text{분산}}
+ \underbrace{\sigma^2}_{\text{줄일 수 없는 오차}}
\]
편향(bias) 은 모델이 단순해서 참 함수를 표현하지 못해 생기는 체계적 오차이고, 분산(variance) 은 학습 데이터가 바뀔 때마다 추정된 모델이 흔들리는 정도다. 모델 복잡도를 올리면 편향은 줄고 분산은 커지므로, 총오차를 최소화하는 복잡도는 둘의 합이 최소가 되는 중간 지점에 있다. KNN에서 이웃 수 \(k\)를 줄이면 복잡도가 올라가고(저편향·고분산), 늘리면 내려간다(고편향·저분산)는 것이 전형적인 예다.
